import os
import json
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _load_image_bytes(image_path: str) -> bytes:
    with open(image_path, "rb") as f:
        return f.read()


def _summarize_labels(labels: Any) -> list[dict]:
    summary = []
    for label in labels or []:
        summary.append(
            {
                "name": label.get("Name"),
                "confidence": float(label.get("Confidence", 0.0)),
                "parents": [p.get("Name") for p in label.get("Parents", []) if isinstance(p, dict)],
            }
        )
    return summary


def _summarize_text(detections: Any) -> list[dict]:
    summary = []
    for item in detections or []:
        summary.append(
            {
                "text": item.get("DetectedText"),
                "confidence": float(item.get("Confidence", 0.0)),
                "type": item.get("Type"),
            }
        )
    return summary


def check_image_safety(
    image_path: str,
    region_name: Optional[str] = None,
    min_confidence: float = 60.0,
) -> Dict[str, Any]:
    """
    Checks an image for unsafe or policy-sensitive visual content using Amazon Rekognition.

    Returns a dict with:
      - unsafe: bool
      - reasons: list[str]
      - labels: list[dict]
      - text: list[dict]
      - raw: original Rekognition response excerpts
    """
    client = boto3.client("rekognition", region_name=region_name) if region_name else boto3.client("rekognition")

    image_bytes = _load_image_bytes(image_path)

    try:
        labels_resp = client.detect_labels(
            Image={"Bytes": image_bytes},
            MinConfidence=min_confidence,
        )
        text_resp = client.detect_text(
            Image={"Bytes": image_bytes},
        )
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Amazon Rekognition request failed: {e}") from e

    labels = labels_resp.get("Labels", [])
    text_detections = text_resp.get("TextDetections", [])

    label_summary = _summarize_labels(labels)
    text_summary = _summarize_text(text_detections)

    unsafe_keywords = {
        "nudity": ["Nudity", "Explicit", "Sexual Activity", "Bare Chest", "Person"],
        "violence": ["Weapon", "Gun", "Knife", "Blood", "Firearm", "Explosive"],
        "drugs": ["Drug", "Medication", "Pill", "Syringe"],
        "self_harm": ["Weapon", "Knife", "Syringe", "Pill"],
        "hate_symbols": ["Swastika", "Nazi", "Confederate"],
        "graphic": ["Blood", "Corpse", "Dead Body", "Skull"],
    }

    reasons = []

    detected_names = {l["name"].lower() for l in label_summary if l.get("name")}
    for category, keywords in unsafe_keywords.items():
        for keyword in keywords:
            if keyword.lower() in detected_names:
                reasons.append(f"Detected label matching {category}: {keyword}")
                break

    text_hits = []
    for item in text_summary:
        text = (item.get("text") or "").lower()
        for category, keywords in unsafe_keywords.items():
            for keyword in keywords:
                if keyword.lower() in text:
                    text_hits.append(f"Detected text matching {category}: {item.get('text')}")
                    break

    reasons.extend(text_hits)

    unsafe = len(reasons) > 0

    return {
        "unsafe": unsafe,
        "reasons": reasons,
        "labels": label_summary,
        "text": text_summary,
        "raw": {
            "label_count": len(labels),
            "text_detection_count": len(text_detections),
        },
    }


if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description="Check an image for unsafe or policy-sensitive visual content.")
    parser.add_argument("image_path", help="Path to the image file")
    parser.add_argument("--region", default=None, help="AWS region for Rekognition")
    parser.add_argument("--min-confidence", type=float, default=60.0, help="Minimum label confidence")
    args = parser.parse_args()

    result = check_image_safety(args.image_path, region_name=args.region, min_confidence=args.min_confidence)
    print(json.dumps(result, indent=2))
